@layer moduix.components {
  .root {
    --_password-input-height: var(--moduix-size-md);
    --_password-input-padding-x: var(--moduix-spacing-3);
    --_password-input-padding-y: var(--moduix-spacing-1);
    --_password-input-font-size: var(--moduix-text-md);
    --_password-input-line-height: var(--moduix-line-height-text-md);
    --_password-input-trigger-size: var(--moduix-size-sm);
    --_password-input-trigger-inset: var(--moduix-spacing-2);
    --_password-input-icon-size: var(--moduix-spacing-4);

    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
    width: var(--moduix-password-input-width, 100%);
    color: var(--moduix-color-foreground);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }

    &[data-size='xs'] {
      --_password-input-height: var(--moduix-size-xs);
      --_password-input-padding-x: var(--moduix-spacing-2);
      --_password-input-padding-y: var(--moduix-spacing-0-5);
      --_password-input-font-size: var(--moduix-text-xs);
      --_password-input-line-height: var(--moduix-line-height-text-xs);
      --_password-input-trigger-size: var(--moduix-spacing-5);
      --_password-input-icon-size: var(--moduix-spacing-3);
    }

    &[data-size='sm'] {
      --_password-input-height: var(--moduix-size-sm);
      --_password-input-padding-x: var(--moduix-spacing-2);
      --_password-input-font-size: var(--moduix-text-sm);
      --_password-input-line-height: var(--moduix-line-height-text-sm);
      --_password-input-trigger-size: var(--moduix-spacing-6);
      --_password-input-trigger-inset: var(--moduix-spacing-1-5);
      --_password-input-icon-size: var(--moduix-spacing-3-5);
    }

    &[data-size='lg'] {
      --_password-input-height: var(--moduix-size-lg);
      --_password-input-padding-x: var(--moduix-spacing-4);
      --_password-input-font-size: var(--moduix-text-lg);
      --_password-input-line-height: var(--moduix-line-height-text-lg);
      --_password-input-trigger-inset: var(--moduix-spacing-3);
    }

    &[data-size='xl'] {
      --_password-input-height: var(--moduix-size-xl);
      --_password-input-padding-x: var(--moduix-spacing-4);
      --_password-input-padding-y: var(--moduix-spacing-2);
      --_password-input-font-size: var(--moduix-text-lg);
      --_password-input-line-height: var(--moduix-line-height-text-lg);
      --_password-input-trigger-size: var(--moduix-spacing-10);
      --_password-input-trigger-inset: var(--moduix-spacing-2-5);
      --_password-input-icon-size: var(--moduix-spacing-5);
    }
  }

  .label {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  /* The bordered shell lives on the control, so the input stops before the trigger. */
  .control {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    min-height: var(--moduix-password-input-height, var(--_password-input-height));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-password-input-radius, var(--moduix-radius-md));
    padding-inline-end: var(--_password-input-trigger-inset);
    background-color: var(--moduix-color-background);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &:focus-within {
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &:focus-within {
        outline-color: var(--moduix-color-destructive);
      }
    }
  }

  .input {
    box-sizing: border-box;
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
    border: 0;
    padding: var(--_password-input-padding-y) var(--_password-input-padding-x);
    background-color: transparent;
    color: inherit;
    font: inherit;
    font-size: var(--_password-input-font-size);
    line-height: var(--_password-input-line-height);
    outline: 0;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }
  }

  .visibilityTrigger {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: var(--_password-input-trigger-size);
    height: var(--_password-input-trigger-size);
    padding: 0;
    border: 0;
    border-radius: var(--moduix-radius-sm);
    background: transparent;
    color: var(--moduix-color-muted-foreground);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    transition:
      color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &:is([data-disabled], [data-readonly]) {
      cursor: default;
    }
  }

  /* The indicator is the visible hover surface; the larger trigger keeps the hit area. */
  .indicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    transition: background-color var(--moduix-transition-default);

    & svg {
      width: var(--_password-input-icon-size);
      height: var(--_password-input-icon-size);
    }
  }

  @media (hover: hover) {
    .visibilityTrigger:not([data-disabled], [data-readonly]):hover {
      color: var(--moduix-color-foreground);

      & .indicator {
        background-color: var(--moduix-color-muted);
      }
    }
  }

  .visibilityTrigger:not([data-readonly]):focus-visible .indicator {
    background-color: var(--moduix-color-muted);
  }
}

import { usePasswordInput, usePasswordInputContext } from '@ark-ui/vue/password-input';
import PasswordInput from './PasswordInput.vue';
import PasswordInputContext from './PasswordInputContext.vue';
import PasswordInputControl from './PasswordInputControl.vue';
import PasswordInputField from './PasswordInputField.vue';
import PasswordInputIndicator from './PasswordInputIndicator.vue';
import PasswordInputInput from './PasswordInputInput.vue';
import PasswordInputLabel from './PasswordInputLabel.vue';
import PasswordInputRootProvider from './PasswordInputRootProvider.vue';
import PasswordInputVisibilityTrigger from './PasswordInputVisibilityTrigger.vue';

export {
  PasswordInput,
  PasswordInputContext,
  PasswordInputControl,
  PasswordInputField,
  PasswordInputIndicator,
  PasswordInputInput,
  PasswordInputLabel,
  PasswordInputRootProvider,
  PasswordInputVisibilityTrigger,
  usePasswordInput,
  usePasswordInputContext,
};

export type {
  PasswordInputControlBaseProps,
  PasswordInputControlProps,
  PasswordInputIndicatorBaseProps,
  PasswordInputIndicatorProps,
  PasswordInputInputBaseProps,
  PasswordInputInputProps,
  PasswordInputLabelBaseProps,
  PasswordInputLabelProps,
  PasswordInputRootBaseProps,
  PasswordInputRootProviderBaseProps,
  PasswordInputVisibilityChangeDetails,
  PasswordInputVisibilityTriggerBaseProps,
  PasswordInputVisibilityTriggerProps,
  UsePasswordInputContext,
  UsePasswordInputProps,
  UsePasswordInputReturn,
} from '@ark-ui/vue/password-input';

export type {
  PasswordInputRootEmits,
  PasswordInputSize,
  Props as PasswordInputRootProps,
} from './PasswordInput.vue';
export type { Props as PasswordInputRootProviderProps } from './PasswordInputRootProvider.vue';
